=== issueContext.ts
// Pure transforms for GitHub issue retrieval: guard the parsed `gh issue view`
// payload and reduce it to the provider-agnostic issue contract the
// gather-context skill consumes in place of the resolve-issue-context delegated
// agent (the agent itself remains for the pr-review CI path). No I/O lives here —
// the CLI in fetch-issue.ts is a thin shell around these functions, so the
// fixture tests in issueContext.test.ts exercise the exact production paths.
//
// Runs under Node's native type stripping (Node >=24) and Bun without a build
// step, so it ships as source at ${CLAUDE_PLUGIN_ROOT}/lib/github/.
//
// The assignee-status vocabulary below stays in sync with
// agents/resolve-issue-context.md Phase 2 and
// skills/branch-create/references/self-assign.md — issueContext.test.ts pins
// the six markers against both files.
//
// Usage:
//   import { buildIssueContext, deriveAssigneeStatus } from "./issueContext.ts";

/** One issue comment in the output contract. */
export interface IssueComment {
  author: string;
  date: string;
  body: string;
}

/**
 * The provider-agnostic issue contract, matching the resolve-issue-context
 * agent's output and lib/linear/fetch-issue.mjs. `truncated` flags that the
 * description or comment list hit an exported bound.
 */
export interface IssueContext {
  source: string;
  issueId: number | null;
  title: string | null;
  status: string;
  labels: string[];
  assignee: string | null;
  url: string | null;
  description: string;
  comments: IssueComment[];
  truncated: boolean;
  resolveError: string | null;
}

/** The `gh issue view --json` fields the transforms consume. */
export interface RawIssue {
  title: string;
  body?: string | null;
  state: string;
  url?: string | null;
  labels?: { name?: string }[];
  assignees?: { login?: string }[];
  comments?: { author?: { login?: string }; createdAt?: string; body?: string }[];
}

/** Description bound in characters. */
export const maxDescriptionLength = 16_000;

/** Comment-list bound. */
export const maxComments = 30;

/** Per-comment body bound in characters. */
export const maxCommentLength = 2_000;

/**
 * The six assignee outcomes' distinguishing markers, one per status string.
 * Pinned by issueContext.test.ts against the two markdown homes of the
 * vocabulary so the three copies cannot drift silently.
 */
export const assigneeStatusMarkers = [
  "(just assigned)",
  "(already assigned)",
  "unassigned — gh not authenticated",
  "unassigned — issue closed",
  "unassigned — permission denied or assignee limit reached",
  "unassigned — gh edit error:",
] as const;

/**
 * Guard the parsed `gh issue view --json` payload: external input, so the
 * load-bearing fields are checked at runtime instead of trusted through a cast.
 * Returns null when the shape does not hold; the CLI degrades that into
 * `resolveError`.
 */
export function parseIssueJson(stdout: string): RawIssue | null {
  let parsed: unknown;
  try {
    parsed = JSON.parse(stdout);
  } catch {
    return null;
  }
  if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) return null;
  const candidate = parsed as Record<string, unknown>;
  if (typeof candidate.title !== "string" || typeof candidate.state !== "string") return null;
  return candidate as unknown as RawIssue;
}

/** The degraded contract shape for a failed fetch; `resolveError` carries the reason. */
export function degradedIssueContext(issueNumber: number | null, error: string): IssueContext {
  return {
    source: issueNumber === null ? "GitHub Issue" : `GitHub Issue #${issueNumber}`,
    issueId: issueNumber,
    title: null,
    status: "unresolved",
    labels: [],
    assignee: null,
    url: null,
    description: "",
    comments: [],
    truncated: false,
    resolveError: error,
  };
}

/** Reduce a guarded issue payload to the bounded contract. */
export function buildIssueContext(issueNumber: number, raw: RawIssue): IssueContext {
  const body = raw.body ?? "";
  const allComments = raw.comments ?? [];
  const comments = allComments.slice(0, maxComments).map((comment) => ({
    author: comment.author?.login ?? "unknown",
    date: (comment.createdAt ?? "").slice(0, 10),
    body: (comment.body ?? "").slice(0, maxCommentLength),
  }));

  return {
    source: `GitHub Issue #${issueNumber}`,
    issueId: issueNumber,
    title: raw.title,
    status: raw.state,
    labels: (raw.labels ?? []).flatMap((label) => (label.name ? [label.name] : [])),
    assignee: null,
    url: raw.url ?? null,
    description: body.slice(0, maxDescriptionLength),
    comments,
    truncated:
      body.length > maxDescriptionLength ||
      allComments.length > maxComments ||
      allComments.some((comment) => (comment.body ?? "").length > maxCommentLength),
    resolveError: null,
  };
}

/** The reads the assign flow produced, injected so the derivation stays pure. */
export interface AssignReads {
  login: string | null;
  state: string;
  assignees: string[];
  editExitCode: number | null;
  editStderr: string;
  verifiedAssignees: string[] | null;
}

/**
 * Derive the assignee status string per the canonical six-outcome flow: no
 * login, closed issue, and already-assigned short-circuit before any edit; a
 * non-zero edit reports its stderr; an exit-0 edit is trusted only after the
 * verifying re-read shows the login, because GitHub drops additions silently on
 * missing permission or the 10-assignee limit.
 */
export function deriveAssigneeStatus(reads: AssignReads): string {
  if (reads.login === null || reads.login === "") return "unassigned — gh not authenticated";
  if (reads.state === "CLOSED") return "unassigned — issue closed";
  if (reads.assignees.includes(reads.login)) return `@${reads.login} (already assigned)`;
  if (reads.editExitCode !== 0) {
    const firstLine = reads.editStderr.split("\n")[0];
    return `unassigned — gh edit error: ${firstLine}`;
  }
  if (reads.verifiedAssignees?.includes(reads.login)) return `@${reads.login} (just assigned)`;
  return "unassigned — permission denied or assignee limit reached";
}
=== fetch-issue.ts
#!/usr/bin/env node
// Fetches a GitHub issue deterministically and prints the provider-agnostic
// issue contract to stdout. Invoked by the gather-context skill in place of the
// resolve-issue-context delegated agent's GitHub path (the agent itself remains
// for the pr-review CI path); Linear inputs use lib/linear/fetch-issue.mjs.
//
// Runs under Node's native type stripping (Node >=24) and Bun — no build step;
// the file ships as source at ${CLAUDE_PLUGIN_ROOT}/lib/github/.
//
// Usage:  node "${CLAUDE_PLUGIN_ROOT}/lib/github/fetch-issue.ts" <owner/repo> <issue-number> [--assign]
//
// Always exits 0 and always prints a single JSON object: on any failure it
// prints the degraded shape with a non-null `resolveError`, so the caller can
// surface the error and STOP rather than proceed against missing data. With
// --assign it also self-assigns the authenticated user (idempotent,
// best-effort — an assignment failure never degrades the fetch) and fills
// `assignee` with one of the six canonical status strings. The one-line
// telemetry summary is mirrored to stderr for CI logs.

import { execFile } from "node:child_process";
import { promisify } from "node:util";

import {
  buildIssueContext,
  degradedIssueContext,
  deriveAssigneeStatus,
  parseIssueJson,
} from "./issueContext.ts";
import type { IssueContext } from "./issueContext.ts";

interface Telemetry {
  durationMs: number;
  requestCount: number;
  payloadBytes: number;
  degradedReads: string[];
}

type HelperOutput = IssueContext & { telemetry: Telemetry };

const execFileAsync = promisify(execFile);
const ghOptions = { maxBuffer: 32 * 1024 * 1024, timeout: 120_000 };

let requestCount = 0;

async function ghRead(args: string[]): Promise<{ stdout: string | null; error: string | null }> {
  requestCount += 1;
  try {
    const { stdout } = await execFileAsync("gh", args, ghOptions);
    return { stdout: stdout.toString(), error: null };
  } catch (error) {
    const e = error as { stderr?: string; message?: string };
    const reason = (e.stderr ?? e.message ?? "").split("\n")[0].slice(0, 200);
    return { stdout: null, error: reason || "gh invocation failed" };
  }
}

const assigneesOf = (stdout: string | null): string[] | null => {
  if (stdout === null) return null;
  try {
    const parsed = JSON.parse(stdout) as { assignees?: { login?: string }[] };
    return (parsed.assignees ?? []).flatMap((entry) => (entry.login ? [entry.login] : []));
  } catch {
    return null;
  }
};

async function selfAssign(repo: string, issueNumber: number, context: IssueContext): Promise<string> {
  const login = (await ghRead(["api", "user", "--jq", ".login"])).stdout?.trim() ?? null;
  const preconditions = {
    login,
    state: context.status,
    assignees: [] as string[],
    editExitCode: null as number | null,
    editStderr: "",
    verifiedAssignees: null as string[] | null,
  };
  if (!login || context.status === "CLOSED") return deriveAssigneeStatus(preconditions);

  const current = await ghRead([
    "issue",
    "view",
    String(issueNumber),
    "-R",
    repo,
    "--json",
    "assignees",
  ]);
  const assignees = assigneesOf(current.stdout) ?? [];
  if (assignees.includes(login)) return deriveAssigneeStatus({ ...preconditions, assignees });

  requestCount += 1;
  let editExitCode = 0;
  let editStderr = "";
  try {
    await execFileAsync(
      "gh",
      ["issue", "edit", String(issueNumber), "-R", repo, "--add-assignee", login],
      ghOptions,
    );
  } catch (error) {
    const e = error as { code?: number; stderr?: string; message?: string };
    editExitCode = typeof e.code === "number" ? e.code : 1;
    editStderr = e.stderr ?? e.message ?? "";
  }
  if (editExitCode !== 0) {
    return deriveAssigneeStatus({ ...preconditions, assignees, editExitCode, editStderr });
  }

  // gh returns exit 0 even when GitHub silently drops the addition, so trust
  // only a verifying re-read.
  const verified = await ghRead([
    "issue",
    "view",
    String(issueNumber),
    "-R",
    repo,
    "--json",
    "assignees",
  ]);
  return deriveAssigneeStatus({
    ...preconditions,
    assignees,
    editExitCode,
    editStderr,
    verifiedAssignees: assigneesOf(verified.stdout) ?? [],
  });
}

async function main(): Promise<HelperOutput> {
  const startedAt = Date.now();
  const args = process.argv.slice(2).filter((arg) => arg !== "--assign");
  const assign = process.argv.includes("--assign");
  const [repo, numberArg] = args;
  const issueNumber = Number.parseInt(numberArg ?? "", 10);

  const finish = (context: IssueContext, degradedReads: string[]): HelperOutput => ({
    ...context,
    telemetry: {
      durationMs: Date.now() - startedAt,
      requestCount,
      payloadBytes: Buffer.byteLength(JSON.stringify(context)),
      degradedReads,
    },
  });

  if (!repo || !repo.includes("/") || Number.isNaN(issueNumber)) {
    return finish(
      degradedIssueContext(
        Number.isNaN(issueNumber) ? null : issueNumber,
        "usage: fetch-issue.ts <owner/repo> <issue-number> [--assign] — arguments missing or invalid",
      ),
      [],
    );
  }

  const fetched = await ghRead([
    "issue",
    "view",
    String(issueNumber),
    "-R",
    repo,
    "--json",
    "title,body,comments,labels,state,url",
  ]);
  if (fetched.stdout === null) {
    return finish(degradedIssueContext(issueNumber, fetched.error ?? "gh invocation failed"), [
      "issue",
    ]);
  }

  const raw = parseIssueJson(fetched.stdout);
  if (raw === null) {
    return finish(
      degradedIssueContext(issueNumber, "gh issue view returned an unrecognized payload shape"),
      ["issue"],
    );
  }

  const context = buildIssueContext(issueNumber, raw);
  if (!assign) return finish(context, []);
  return finish({ ...context, assignee: await selfAssign(repo, issueNumber, context) }, []);
}

const output = await main();
process.stderr.write(`fetch-issue telemetry: ${JSON.stringify(output.telemetry)}\n`);
process.stdout.write(JSON.stringify(output));
